from collections import Counter
def solve(g):
    R,C=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    anchor=min(cnt,key=cnt.get)
    bg=max(cnt,key=cnt.get)
    o=[r[:] for r in g]
    for r in range(R):
        pos=[c for c in range(C) if g[r][c]==anchor]
        for a,b in zip(pos,pos[1:]):
            for c in range(a+1,b):
                if g[r][c]==bg: o[r][c]=3
    for c in range(C):
        pos=[r for r in range(R) if g[r][c]==anchor]
        for a,b in zip(pos,pos[1:]):
            for r in range(a+1,b):
                if g[r][c]==bg: o[r][c]=3
    return o
